tools.args:
{"command":"$ErrorActionPreference='SilentlyContinue'
"=== OS ==="; (Get-CimInstance Win32_OperatingSystem).Caption
"=== Workspace ==="; Get-ChildItem -Force "C:\Users\spay\.minimax\sessions\mvs_11a90c358d7b4d858575a99de281ffa0\workspace" | Select-Object Name,Length | Format-Table -AutoSize | Out-String
"=== Tools ==="
foreach($c in 'python','python3','py','node','ollama','screenpipe','git','rg'){ $p=(Get-Command $c -ErrorAction SilentlyContinue); if($p){"$c => $($p.Source)"} else {"$c => MISSING"} }
"=== GPU ==="
try{ (Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty Name) -join ' | ' }catch{}
"=== RAM ==="
[math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory/1GB,1)","description":"Reconcile OS, workspace and installed tooling"}

{"command":"$ErrorActionPreference='SilentlyContinue'
foreach($d in 'C:\Users\spay\.activity-tracker','C:\Users\spay\activity-tracker','C:\Users\spay\daily-summaries','C:\Users\spay\screenpipe','C:\Users\spay\screenpipe-exports','C:\Users\spay\.screenpipe'){
  "=== $d ==="
  if(Test-Path $d){ Get-ChildItem $d -Force | Sort-Object LastWriteTime -Descending | Select-Object -First 12 Name,Length,LastWriteTime | Format-Table -AutoSize | Out-String } else { "missing" }
}","description":"Inspect existing activity-tracking folders"}
